import * as React from 'react';
import {Tabs as TB,Accordion as AC,Collapsible as CO,DropdownMenu as DM,ContextMenu as CM,Menubar as MB,NavigationMenu as NM,ScrollArea as SA} from 'radix-ui';
import {Search,Menu,ChevronRight} from 'lucide-react';
import {Button} from './basic';
import {Modal} from './overlays';
export function Tabs({items,defaultValue}:{items:{value:string;label:string;content:React.ReactNode}[];defaultValue?:string}){return <TB.Root defaultValue={defaultValue||items[0]?.value}><TB.List aria-label="Sections" className="mb-5 flex flex-wrap gap-1 rounded-lg bg-surface p-1">{items.map(i=><TB.Trigger key={i.value} value={i.value} className="rounded-md px-4 py-2 text-sm data-[state=active]:bg-card">{i.label}</TB.Trigger>)}</TB.List>{items.map(i=><TB.Content key={i.value} value={i.value}>{i.content}</TB.Content>)}</TB.Root>}
export function Accordion({items}:{items:{title:string;content:React.ReactNode}[]}){return <AC.Root type="single" collapsible>{items.map((i,n)=><AC.Item key={n} value={String(n)} className="border-b border-line"><AC.Header><AC.Trigger className="flex w-full items-center justify-between py-5 text-start text-sm font-medium">{i.title}<ChevronRight className="size-4 shrink-0"/></AC.Trigger></AC.Header><AC.Content className="pb-5 text-sm leading-relaxed text-muted">{i.content}</AC.Content></AC.Item>)}</AC.Root>}
export function Collapsible({title,children}:{title:string;children:React.ReactNode}){return <CO.Root><CO.Trigger asChild><Button tone="outline">{title}</Button></CO.Trigger><CO.Content className="mt-4 rounded-lg bg-surface p-4 text-sm">{children}</CO.Content></CO.Root>}
export type MenuOption={label:string;onSelect:()=>void;disabled?:boolean;danger?:boolean};
const menuClass='cursor-pointer rounded-md px-3 py-2 text-sm outline-none data-[highlighted]:bg-surface data-[disabled]:opacity-40';
export function DropdownMenu({trigger,items}:{trigger:React.ReactElement;items:MenuOption[]}){return <DM.Root><DM.Trigger asChild>{trigger}</DM.Trigger><DM.Portal><DM.Content className="a-popup min-w-44" sideOffset={6}>{items.map(i=><DM.Item key={i.label} disabled={i.disabled} onSelect={i.onSelect} className={menuClass+(i.danger?' text-danger':'')}>{i.label}</DM.Item>)}</DM.Content></DM.Portal></DM.Root>}
export function ContextMenu({children,items}:{children:React.ReactNode;items:MenuOption[]}){return <CM.Root><CM.Trigger className="block">{children}</CM.Trigger><CM.Portal><CM.Content className="a-popup min-w-44">{items.map(i=><CM.Item key={i.label} disabled={i.disabled} onSelect={i.onSelect} className={menuClass}>{i.label}</CM.Item>)}</CM.Content></CM.Portal></CM.Root>}
export function Menubar({menus}:{menus:{label:string;items:MenuOption[]}[]}){return <MB.Root className="flex rounded-lg border border-line p-1">{menus.map(m=><MB.Menu key={m.label}><MB.Trigger className="rounded px-3 py-2 text-sm data-[state=open]:bg-surface">{m.label}</MB.Trigger><MB.Portal><MB.Content className="a-popup min-w-44">{m.items.map(i=><MB.Item key={i.label} disabled={i.disabled} onSelect={i.onSelect} className={menuClass}>{i.label}</MB.Item>)}</MB.Content></MB.Portal></MB.Menu>)}</MB.Root>}
export function NavigationMenu({items}:{items:{label:string;href:string}[]}){return <NM.Root aria-label="Main navigation"><NM.List className="flex flex-wrap gap-5">{items.map(i=><NM.Item key={i.href}><NM.Link href={i.href} className="text-sm underline-offset-4 hover:underline">{i.label}</NM.Link></NM.Item>)}</NM.List></NM.Root>}
export function Breadcrumb({items}:{items:{label:string;href?:string}[]}){return <nav aria-label="Breadcrumb"><ol className="flex flex-wrap items-center gap-2 text-sm">{items.map((i,n)=><li key={n} className="flex items-center gap-2">{n>0&&<ChevronRight aria-hidden className="size-3 text-muted"/>}{i.href?<a href={i.href} className="text-muted hover:underline">{i.label}</a>:<span aria-current="page">{i.label}</span>}</li>)}</ol></nav>}
export function Pagination({page,total,onChange}:{page:number;total:number;onChange:(p:number)=>void}){return <nav aria-label="Pagination" className="flex items-center gap-3"><Button tone="outline" size="sm" disabled={page<=1} onClick={()=>onChange(page-1)}>Previous</Button><span className="text-sm" aria-live="polite">Page {page} of {total}</span><Button tone="outline" size="sm" disabled={page>=total} onClick={()=>onChange(page+1)}>Next</Button></nav>}
export function ScrollArea({children,className='h-44'}:{children:React.ReactNode;className?:string}){return <SA.Root className={'relative overflow-hidden '+className}><SA.Viewport className="size-full rounded-inherit">{children}</SA.Viewport><SA.Scrollbar orientation="vertical" className="w-2 bg-surface p-0.5"><SA.Thumb className="rounded-full bg-muted/50"/></SA.Scrollbar></SA.Root>}
export function Sidebar({items,children}:{items:{label:string;href:string}[];children:React.ReactNode}){return <div className="grid min-h-60 gap-6 sm:grid-cols-[160px_1fr]"><aside className="border-b border-line pb-4 sm:border-b-0 sm:border-e sm:pe-4"><NavigationMenu items={items}/></aside><div>{children}</div></div>}
export function Command({items}:{items:{label:string;onSelect:()=>void}[]}){const [open,setOpen]=React.useState(false),[q,setQ]=React.useState('');const input=React.useRef<HTMLInputElement>(null);const [active,setActive]=React.useState(0);const filtered=items.filter(i=>i.label.toLowerCase().includes(q.toLowerCase()));return <Modal open={open} onOpenChange={setOpen} trigger={<Button tone="outline"><Search className="size-4"/>Search commands</Button>} title="Commands" description="Search and run a command."><input ref={input} value={q} onChange={e=>{setQ(e.target.value);setActive(0)}} aria-label="Search commands" role="combobox" aria-expanded="true" aria-controls="a-command-list" aria-activedescendant={filtered.length?'a-command-'+active:undefined} className="a-input" onKeyDown={e=>{if(e.key==='ArrowDown'){e.preventDefault();setActive(i=>Math.min(i+1,filtered.length-1))}if(e.key==='ArrowUp'){e.preventDefault();setActive(i=>Math.max(i-1,0))}if(e.key==='Enter'&&filtered[active]){filtered[active].onSelect();setOpen(false)}}}/><ul id="a-command-list" role="listbox" aria-label="Commands" className="mt-3">{filtered.map((i,n)=><li role="option" aria-selected={n===active} id={'a-command-'+n} key={i.label} className={'cursor-pointer rounded p-3 text-sm '+(n===active?'bg-surface':'')} onClick={()=>{i.onSelect();setOpen(false)}}>{i.label}</li>)}</ul>{!filtered.length&&<p role="status" className="p-3 text-sm text-muted">No commands found.</p>}</Modal>}

import * as React from 'react';
import {LoaderCircle} from 'lucide-react';
import {cx} from './utils';
export type ButtonProps=React.ButtonHTMLAttributes<HTMLButtonElement>&{tone?:'primary'|'secondary'|'outline'|'quiet'|'danger'|'accent';size?:'sm'|'md'|'lg';loading?:boolean};
export const Button=React.forwardRef<HTMLButtonElement,ButtonProps>(function Button({tone='primary',size='md',loading=false,disabled,children,className,type='button',...props},ref){
return <button ref={ref} type={type} disabled={disabled||loading} aria-busy={loading||undefined} className={cx('a-button',{'bg-ink text-paper hover:bg-ink/85':tone==='primary','bg-surface text-ink hover:bg-surface/70':tone==='secondary','border border-line bg-transparent text-ink':tone==='outline','bg-transparent text-ink hover:bg-surface':tone==='quiet','bg-danger text-white':tone==='danger','bg-gold text-[#181818]':tone==='accent'},{'min-h-9 px-3 text-xs':size==='sm','min-h-11 px-4 text-sm':size==='md','min-h-13 px-6 text-base':size==='lg'},className)} {...props}>{loading&&<LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" aria-hidden/>}{children}</button>});
export function Badge({tone='neutral',className,children,...props}:React.HTMLAttributes<HTMLSpanElement>&{tone?:'neutral'|'success'|'warning'|'danger'}){return <span className={cx('inline-flex rounded-full px-2.5 py-1 text-xs font-medium',{'bg-surface text-ink':tone==='neutral','bg-success/10 text-success':tone==='success','bg-gold/20 text-ink':tone==='warning','bg-danger/10 text-danger':tone==='danger'},className)} {...props}>{children}</span>}
export function Card({className,...props}:React.HTMLAttributes<HTMLElement>){return <article className={cx('rounded-xl border border-line bg-card p-6',className)} {...props}/>}
export function CardHeader({className,...props}:React.HTMLAttributes<HTMLDivElement>){return <div className={cx('mb-5 space-y-2',className)} {...props}/>}
export function CardTitle({className,...props}:React.HTMLAttributes<HTMLHeadingElement>){return <h3 className={cx('text-xl font-medium tracking-tight',className)} {...props}/>}
export function CardDescription({className,...props}:React.HTMLAttributes<HTMLParagraphElement>){return <p className={cx('text-sm leading-relaxed text-muted',className)} {...props}/>}
export function CardFooter({className,...props}:React.HTMLAttributes<HTMLDivElement>){return <div className={cx('mt-6 flex flex-wrap items-center gap-3',className)} {...props}/>}
export const Separator=({className,...props}:React.HTMLAttributes<HTMLHRElement>)=><hr className={cx('my-5 border-line',className)} {...props}/>;
export function Skeleton({className,...props}:React.HTMLAttributes<HTMLDivElement>){return <div aria-hidden className={cx('h-4 rounded bg-surface animate-pulse motion-reduce:animate-none',className)} {...props}/>}
export function Spinner({label='Loading'}:{label?:string}){return <span role="status" className="inline-flex items-center gap-2 text-sm"><LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" aria-hidden/>{label}</span>}
export function Alert({title,children,tone='info'}:{title:string;children?:React.ReactNode;tone?:'info'|'error'|'success'}){return <div role={tone==='error'?'alert':'status'} className={cx('rounded-xl border p-4 text-sm',tone==='error'?'border-danger/40 bg-danger/5':tone==='success'?'border-success/40 bg-success/5':'border-line bg-surface/50')}><p className="font-semibold">{title}</p>{children&&<div className="mt-2 leading-relaxed">{children}</div>}</div>}
export function Empty({title,children,action}:{title:string;children?:React.ReactNode;action?:React.ReactNode}){return <div className="rounded-xl border border-dashed border-line p-10 text-center"><h3 className="font-editorial text-2xl">{title}</h3><div className="mx-auto my-4 max-w-sm text-sm text-muted">{children}</div>{action}</div>}
export function Progress({value,label}:{value:number;label:string}){const current=Math.max(0,Math.min(100,value));return <div><div className="mb-2 flex justify-between text-sm"><span>{label}</span><span>{current}%</span></div><progress aria-label={label} value={current} max={100} className="h-2 w-full overflow-hidden rounded-full accent-terracotta"/></div>}
export function Avatar({src,name}:{src?:string;name:string}){const [failed,setFailed]=React.useState(false);return <span className="inline-flex size-10 items-center justify-center overflow-hidden rounded-full bg-surface text-sm font-semibold" role="img" aria-label={name}>{src&&!failed?<img src={src} alt="" onError={()=>setFailed(true)} className="size-full object-cover"/>:name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span>}
export function AspectRatio({ratio=16/9,children,className}:{ratio?:number;children:React.ReactNode;className?:string}){return <div style={{aspectRatio:ratio}} className={cx('overflow-hidden rounded-xl',className)}>{children}</div>}
export const Kbd=({children}:{children:React.ReactNode})=><kbd className="rounded border border-line bg-surface px-1.5 py-0.5 font-mono text-xs">{children}</kbd>;
export const ButtonGroup=({children,label}:{children:React.ReactNode;label:string})=><div role="group" aria-label={label} className="flex flex-wrap gap-2">{children}</div>;
export function Item({title,description,action}:{title:string;description?:string;action?:React.ReactNode}){return <div className="flex items-center justify-between gap-4 border-b border-line py-4"><div><p className="font-medium">{title}</p>{description&&<p className="text-sm text-muted">{description}</p>}</div>{action}</div>}
export function Typography({children,as:Tag='p',editorial=false,className}:{children:React.ReactNode;as?:'h1'|'h2'|'h3'|'p';editorial?:boolean;className?:string}){return <Tag className={cx(editorial?'font-editorial':'font-sans',Tag==='h1'?'text-5xl leading-tight tracking-tight':Tag==='h2'?'text-3xl tracking-tight':Tag==='h3'?'text-xl':'leading-relaxed',className)}>{children}</Tag>}
export function Direction({dir,children}:{dir:'ltr'|'rtl';children:React.ReactNode}){return <div dir={dir}>{children}</div>}

import {clsx,type ClassValue} from 'clsx';
import {twMerge} from 'tailwind-merge';
export const cx=(...values:ClassValue[])=>twMerge(clsx(values));

import * as React from 'react';
import {Dialog as D,AlertDialog as A,Popover as P,Tooltip as T,HoverCard as H,Toast as RT} from 'radix-ui';
import {X} from 'lucide-react';
import {Button} from './basic';
import {cx} from './utils';
type ModalProps={trigger?:React.ReactElement;title:string;description:string;children:React.ReactNode;open?:boolean;onOpenChange?:(v:boolean)=>void;footer?:React.ReactNode;placement?:'center'|'right'|'bottom'};
export function Modal({trigger,title,description,children,open,onOpenChange,footer,placement='center'}:ModalProps){return <D.Root open={open} onOpenChange={onOpenChange}>{trigger&&<D.Trigger asChild>{trigger}</D.Trigger>}<D.Portal><D.Overlay className="a-overlay"/><D.Content className={cx('fixed z-50 flex max-h-[90dvh] flex-col border border-line bg-card text-ink shadow-xl outline-none',placement==='center'?'left-1/2 top-1/2 w-[min(560px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 rounded-2xl':placement==='right'?'right-0 top-0 h-dvh max-h-dvh w-[min(460px,100%)]':'bottom-0 left-0 right-0 max-h-[85dvh] rounded-t-2xl')}><div className="border-b border-line px-6 py-5 pe-14"><D.Title className="font-editorial text-2xl">{title}</D.Title><D.Description className="mt-2 text-sm text-muted">{description}</D.Description></div><div className="overflow-y-auto p-6">{children}</div>{footer&&<div className="flex flex-wrap justify-end gap-3 border-t border-line p-5">{footer}</div>}<D.Close aria-label="Close dialog" className="absolute end-4 top-4 rounded-md p-2 hover:bg-surface"><X className="size-4"/></D.Close></D.Content></D.Portal></D.Root>}
export const Dialog=Modal;
export function Sheet(props:Omit<ModalProps,'placement'>){return <Modal {...props} placement="right"/>}
export function Drawer(props:Omit<ModalProps,'placement'>){return <Modal {...props} placement="bottom"/>}
export function AlertDialog({trigger,title,description,onConfirm,confirmLabel='Confirm'}:{trigger:React.ReactElement;title:string;description:string;onConfirm:()=>void;confirmLabel?:string}){return <A.Root><A.Trigger asChild>{trigger}</A.Trigger><A.Portal><A.Overlay className="a-overlay"/><A.Content className="fixed left-1/2 top-1/2 z-50 w-[min(480px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 rounded-2xl border border-line bg-card p-6 text-ink shadow-xl"><A.Title className="font-editorial text-2xl">{title}</A.Title><A.Description className="my-4 text-sm leading-relaxed text-muted">{description}</A.Description><div className="flex justify-end gap-3"><A.Cancel asChild><Button tone="outline">Cancel</Button></A.Cancel><A.Action asChild><Button tone="danger" onClick={onConfirm}>{confirmLabel}</Button></A.Action></div></A.Content></A.Portal></A.Root>}
export function Popover({trigger,children,label}:{trigger:React.ReactElement;children:React.ReactNode;label:string}){return <P.Root><P.Trigger asChild>{trigger}</P.Trigger><P.Portal><P.Content aria-label={label} sideOffset={8} className="a-popup w-72 p-5">{children}<P.Close aria-label="Close popover" className="absolute end-1 top-1 p-1"><X className="size-3"/></P.Close></P.Content></P.Portal></P.Root>}
export function Tooltip({children,content}:{children:React.ReactElement;content:string}){return <T.Provider delayDuration={250}><T.Root><T.Trigger asChild>{children}</T.Trigger><T.Portal><T.Content sideOffset={6} className="z-[60] rounded-md bg-ink px-3 py-2 text-xs text-paper">{content}<T.Arrow className="fill-ink"/></T.Content></T.Portal></T.Root></T.Provider>}
export function HoverCard({trigger,children}:{trigger:React.ReactElement;children:React.ReactNode}){return <H.Root><H.Trigger asChild>{trigger}</H.Trigger><H.Portal><H.Content sideOffset={8} className="a-popup w-72 p-5">{children}</H.Content></H.Portal></H.Root>}
export function ToastDemo(){const [open,setOpen]=React.useState(false);return <RT.Provider swipeDirection="right"><Button tone="outline" onClick={()=>setOpen(true)}>Show notification</Button><RT.Root open={open} onOpenChange={setOpen} className="rounded-xl border border-line bg-card p-5 shadow-xl"><RT.Title className="font-medium">Changes saved</RT.Title><RT.Description className="mt-1 text-sm text-muted">Your local example has been updated.</RT.Description><RT.Close className="mt-3 text-sm underline">Dismiss</RT.Close></RT.Root><RT.Viewport className="fixed bottom-4 right-4 z-[70] m-0 w-[min(360px,calc(100%-32px))] list-none outline-none"/></RT.Provider>}
export {RT as Toast};

@import "tailwindcss";
@source "./**/*.{ts,tsx}";
@theme {
 --color-paper:#f4f1e9;--color-ink:#20201d;--color-muted:#656158;--color-line:#d2ccc0;
 --color-surface:#e8e3d8;--color-card:#faf8f2;--color-terracotta:#ac4333;--color-gold:#edbd52;
 --color-danger:#a32925;--color-success:#326145;
 --font-sans:'DM Sans Variable',Arial,sans-serif;--font-editorial:'Lora Variable',Georgia,serif;
}
@layer base {
 *{border-color:var(--color-line)}
 body{background:var(--color-paper);color:var(--color-ink);font-family:var(--font-sans);margin:0;-webkit-font-smoothing:antialiased}
 button:not(:disabled),summary{cursor:pointer}
 :focus-visible{outline:2px solid var(--color-terracotta);outline-offset:4px}
}
@layer components {
 .a-button{@apply inline-flex shrink-0 items-center justify-center gap-2 rounded-lg font-medium transition-colors disabled:pointer-events-none disabled:opacity-45 focus-visible:outline-2 focus-visible:outline-offset-4}
 .a-input{@apply min-h-11 w-full rounded-lg border border-line bg-card px-3 py-2 text-sm text-ink placeholder:text-muted disabled:opacity-50 aria-invalid:border-danger}
 .a-overlay{@apply fixed inset-0 z-50 bg-black/40 backdrop-blur-xs}
 .a-popup{@apply z-50 rounded-xl border border-line bg-card p-2 text-ink shadow-xl}
}
[data-theme=dark]{--color-paper:#191a18;--color-ink:#eeeade;--color-muted:#b8b3a8;--color-line:#45463f;--color-surface:#30312c;--color-card:#22241f;--color-terracotta:#e69477;--color-danger:#f2938c;--color-success:#8fc8a4}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
